using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.RunModifiers;

public class RunModifiersManager : ReferenceSingleton<RunModifiersManager>
{
	[Header("Assets")]
	[SerializeField]
	private RunModifiersHandler runModifiersHandler;

	[HideInInspector]
	public List<Action> StartOfBattleRunModifierActions = new List<Action>();

	[HideInInspector]
	public List<Action> StartOfTurnRunModifierActions = new List<Action>();

	[HideInInspector]
	public bool DiceHoarderRunModifierActive;

	[HideInInspector]
	public float MonstrousVitalityRunModifierAmount;

	[HideInInspector]
	public GrimExchangeRunModifier GrimExchangeRunModifier;

	[HideInInspector]
	public OnlySpecificChestRunModifier OnlySpecificChestRunModifier;

	[HideInInspector]
	public bool GoddessTrickeryRunModifierActive;

	[HideInInspector]
	public bool TimeDistortionRunModifier;

	[HideInInspector]
	public bool StarShowerRunModifier;

	[HideInInspector]
	public DiceRewardForgeModifier FatalJinxDiceRewardForgeModifier;

	[HideInInspector]
	public DiceRewardForgeModifier DicesmithFeverDiceRewardForgeModifier;

	[HideInInspector]
	public List<StartingEffect> SentinelStartingEffectsRunModifiers = new List<StartingEffect>();

	[HideInInspector]
	public List<Action> OnShuffleDicePoolRunModifierActions = new List<Action>();

	[HideInInspector]
	public StellarParadoxRunModifier StellarParadoxRunModifier;

	[HideInInspector]
	public StellarHeritageRunModifier StellarHeritageRunModifier;

	[HideInInspector]
	public Func<OmenData, bool> DicelessAnomalyRunModifierAction;

	[HideInInspector]
	public Action<List<Dice>> CursedForgingRunModifierAction;

	[HideInInspector]
	public ClearingReward BrokenForgeRunModifierClearingReward;

	[HideInInspector]
	public Func<int, int> ForgeShopShopsAreMoreExpensiveRunModifierAction;

	[HideInInspector]
	public Func<int, int> SentinelShopShopsAreMoreExpensiveRunModifierAction;

	[HideInInspector]
	public Func<int, int> EpicShopShopsAreMoreExpensiveRunModifierAction;

	[HideInInspector]
	public HeartModificationRunModifier HeartModificationRunModifier;

	[HideInInspector]
	public RestlessJourneyRunModifier RestlessJourneyRunModifier;

	[HideInInspector]
	public BlessedPathRunModifier BlessedPathRunModifier;

	[HideInInspector]
	public OmenTier ReplaceBlessingsRunModifierOmenTier;

	[HideInInspector]
	public DraftDiceRunModifier DraftDiceRunModifier;

	[HideInInspector]
	public MysteriousAdventureRunModifier MysteriousAdventureRunModifier;

	[HideInInspector]
	public bool MalfunctioningSentinelsRunModifierActive;

	[HideInInspector]
	public ReliableEightRunModifier ReliableEightRunModifier;

	[HideInInspector]
	public bool AstreasHeartActive;

	[HideInInspector]
	public VirtuelessRunModifier VirtuelessRunModifier;

	[HideInInspector]
	public DiceShortageRunModifier DiceShortageRunModifier;

	[HideInInspector]
	public ScorchedBattlefieldRunModifier ScorchedBattlefieldRunModifier;

	[HideInInspector]
	public ForgottenKnowledgeRunModifier ForgottenKnowledgeRunModifier;

	[HideInInspector]
	public List<Action<Dice>> OnDicePlayedRunModifierActions = new List<Action<Dice>>();

	[HideInInspector]
	public List<Action> OnVirtuePlayedRunModifierActions = new List<Action>();

	[HideInInspector]
	public HarshEconomyRunModifier HarshEconomyRunModifier;

	public RunModifiersHandler RunModifiersHandler => runModifiersHandler;

	public void InitializeRunModifiers()
	{
		runModifiersHandler.ActiveRunModifiers.InteractThroughItems(delegate(RunModifier item)
		{
			item.Initialize();
		});
	}

	public void InitializeRunModifiersNewRunBeforeResetAssetsToDefaultState()
	{
		runModifiersHandler.ActiveRunModifiers.InteractThroughItems(delegate(RunModifier item)
		{
			item.InitializeNewRunBeforeResetAssetsToDefaultState();
		});
	}

	public void InitializeRunModifiersNewRun()
	{
		int num = -1;
		for (int i = 0; i < runModifiersHandler.ActiveRunModifiers.Count; i++)
		{
			if (!(runModifiersHandler.ActiveRunModifiers[i] is ReliableEightRunModifier))
			{
				runModifiersHandler.ActiveRunModifiers[i].InitializeNewRun();
			}
			else
			{
				num = i;
			}
		}
		if (num > -1)
		{
			runModifiersHandler.ActiveRunModifiers[num].InitializeNewRun();
		}
	}

	public IEnumerator ActivateStartOfBattleRunModifierActions()
	{
		for (int i = 0; i < StartOfBattleRunModifierActions.Count; i++)
		{
			StartOfBattleRunModifierActions[i]();
			yield return new WaitForSeconds(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.TimeBetweenOmenFeedback);
		}
	}

	public IEnumerator ActivateStartOfTurnRunModifierActions()
	{
		if (StartOfTurnRunModifierActions.Count > 0)
		{
			yield return new WaitForSeconds(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.TimeBetweenOmenFeedback / 2f);
		}
		for (int i = 0; i < StartOfTurnRunModifierActions.Count; i++)
		{
			StartOfTurnRunModifierActions[i]();
			yield return new WaitForSeconds(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.TimeBetweenOmenFeedback);
		}
	}

	public void EndOfBattleInitialize()
	{
		for (int i = 0; i < runModifiersHandler.ActiveRunModifiers.Count; i++)
		{
			runModifiersHandler.ActiveRunModifiers[i].EndOfBattleInitialize();
		}
	}

	public List<Dice> GetModifiedDiceRunModifier(List<Dice> diceList)
	{
		for (int i = 0; i < diceList.Count; i++)
		{
			if (FatalJinxDiceRewardForgeModifier != null)
			{
				diceList[i] = FatalJinxDiceRewardForgeModifier.GetModifiedDice(diceList[i]);
			}
			if (DicesmithFeverDiceRewardForgeModifier != null)
			{
				diceList[i] = DicesmithFeverDiceRewardForgeModifier.GetModifiedDice(diceList[i]);
			}
		}
		return diceList;
	}

	public void CheckStellarParadoxRunModifierGainAdditionalDiceOnDiceRewardInstance(Vector3 spawnPosition, Dice dice, PlayerDiceInventoryData allDicePool)
	{
		if (StellarParadoxRunModifier != null)
		{
			StellarParadoxRunModifier.GainAdditionalDiceOnDiceRewardInstance(spawnPosition, dice, allDicePool);
		}
	}

	public int GetForgeShopShopsAreMoreExpensiveRunModifierModifiedCost(int cost)
	{
		if (ForgeShopShopsAreMoreExpensiveRunModifierAction != null)
		{
			return ForgeShopShopsAreMoreExpensiveRunModifierAction(cost);
		}
		return cost;
	}

	public int GetSentinelShopShopsAreMoreExpensiveRunModifierModifiedCost(int cost)
	{
		if (SentinelShopShopsAreMoreExpensiveRunModifierAction != null)
		{
			return SentinelShopShopsAreMoreExpensiveRunModifierAction(cost);
		}
		return cost;
	}

	public int GetEpicShopShopsAreMoreExpensiveRunModifierModifiedCost(int cost)
	{
		if (EpicShopShopsAreMoreExpensiveRunModifierAction != null)
		{
			return EpicShopShopsAreMoreExpensiveRunModifierAction(cost);
		}
		return cost;
	}

	public void ActivateOnDicePlayedRunModifiers(Dice dice)
	{
		for (int i = 0; i < OnDicePlayedRunModifierActions.Count; i++)
		{
			OnDicePlayedRunModifierActions[i](dice);
		}
	}

	public void ActivateOnVirtuePlayedRunModifier()
	{
		for (int i = 0; i < OnVirtuePlayedRunModifierActions.Count; i++)
		{
			OnVirtuePlayedRunModifierActions[i]();
		}
	}
}
